"""Load configuration from files and strings."""

import os

from miniconf.errors import ConfigError
from miniconf.parser import parse_lines

_INCLUDE = "@include"


def _include_target(line):
    """Return the include path if ``line`` is an include directive, else None."""
    parts = line.split(None, 1)
    if not parts or parts[0] != _INCLUDE:
        return None
    if len(parts) < 2 or not parts[1].strip():
        raise ConfigError("@include requires a path")
    return parts[1].strip()


def _expand(path, stack, included):
    real = os.path.realpath(path)
    if real in stack:
        raise ConfigError("include cycle detected at {}".format(path))
    try:
        with open(path, "r", encoding="utf-8") as fh:
            lines = fh.read().splitlines()
    except OSError as exc:
        if included:
            raise ConfigError("cannot read include {}: {}".format(path, exc))
        raise
    except UnicodeDecodeError as exc:
        if included:
            raise ConfigError("cannot decode include {}: {}".format(path, exc))
        raise

    stack = stack + (real,)
    base = os.path.dirname(os.path.abspath(path))
    out = []
    for raw in lines:
        target = _include_target(raw)
        if target is None:
            out.append(raw)
            continue
        out.extend(_expand(os.path.join(base, target), stack, True))
    return out


def load(path):
    """Read and parse the configuration file at ``path``.

    ``@include <path>`` lines are replaced inline by the contents of the
    referenced file, resolved relative to the including file's directory.
    """
    return parse_lines(_expand(path, (), False))


def loads(text):
    """Parse configuration from a string."""
    return parse_lines(text.splitlines())
